patches.replace:
.title-foot {
  position: absolute;
  z-index: 2;
  left: .44rem;
  right: .44rem;
  bottom: .3rem;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  font-size: .13rem;
  color: var(--text-dim);
}
.title-foot__meta { display: inline-flex; align-items: center; gap: .14rem; }
.title-foot__update { background: none; border: 0; padding: 0; font-family: var(--font-display); font-size: .11rem; line-height: 1.2; letter-spacing: .18em; color: var(--text-dim); cursor: pointer; }
.title-foot__update:hover { color: var(--mint-700, #4ed8af); }
